from itertools import product

def dnf(f, names):
    terms = []
    for bits in product([0, 1], repeat=len(names)):
        if f(*bits):
            terms.append("".join(n if b else n + "'" for n, b in zip(names, bits)))
    return " + ".join(terms) or "0"

majority = lambda x, y, z: int(x + y + z >= 2)
print("көпшілік:", dnf(majority, "xyz"))

def full_adder(a, b, c):
    s = a ^ b ^ c
    cout = (a & b) | (c & (a ^ b))
    return s, cout

def add_bits(x, y, n=8):
    c, out = 0, 0
    for i in range(n):
        s, c = full_adder((x >> i) & 1, (y >> i) & 1, c)
        out |= s << i
    return out, c                      # c - толып кету (overflow) тасымалы

print(add_bits(6, 7, 4), add_bits(200, 100, 8))
print("барлығы дұрыс:", all(add_bits(x, y, 8) == ((x + y) % 256, (x + y) // 256) for x in range(256) for y in range(256)))

nand = lambda a, b: 1 - (a & b)
xor_from_nand = lambda x, y: nand(nand(x, nand(x, y)), nand(y, nand(x, y)))
print("XOR = 4 NAND:", all(xor_from_nand(x, y) == x ^ y for x in (0, 1) for y in (0, 1)))
